from typing import List, Dict, Any, Optional

class TranscriptionJob:
    def __init__(self, job_id: str, status: str, transcript_uri: Optional[str] = None):
        self.job_id = job_id
        self.status = status
        self.transcript_uri = transcript_uri

class TranscriptSegment:
    def __init__(self, start_time: float, end_time: float, speaker_label: str, content: str, words: Optional[List[Dict[str, Any]]] = None):
        self.start_time = start_time
        self.end_time = end_time
        self.speaker_label = speaker_label
        self.content = content
        self.words = words

class TranscriptionResult:
    def __init__(self, job_id: str, status: str, language_code: str, segments: List[TranscriptSegment]):
        self.job_id = job_id
        self.status = status
        self.language_code = language_code
        self.segments = segments

import boto3

class SpeechClient:
    def __init__(self, region_name: str):
        self.transcribe_client = boto3.client("transcribe", region_name=region_name)
        self.translate_client = boto3.client("translate", region_name=region_name)
        self.comprehend_client = boto3.client("comprehend", region_name=region_name)
        self.bedrock_runtime_client = boto3.client("bedrock-runtime", region_name=region_name)

    def get_transcribe_client(self):
        return self.transcribe_client

    def get_translate_client(self):
        return self.translate_client

    def get_comprehend_client(self):
        return self.comprehend_client

    def get_bedrock_runtime_client(self):
        return self.bedrock_runtime_client

import uuid

import boto3

def diarized_transcript(payload: dict, config: dict = None) -> dict:
    config = config or {}
    client = boto3.client("transcribe", region_name=config.get("region"))
    job_id = config.get("job_name") or f"diarization-{uuid.uuid4().hex}"
    response = client.start_transcription_job(
        TranscriptionJobName=job_id,
        LanguageCode=payload["language_code"],
        Media={"MediaFileUri": payload["audio_uri"]},
        Settings={
            "ShowSpeakerLabels": True,
            "MaxSpeakerLabels": payload.get("max_speaker_labels", 2) # Default to 2 speakers if not provided
        }
    )
    return {
        "job_id": response["TranscriptionJob"]["TranscriptionJobName"],
        "status": "SUBMITTED",
    }
